// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, EmergencyOracle} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        // 1. keep params in the admissible domain: caller must be a real address
        vm.assume(actor != address(0));

        // 2. drive c through newEmergencyOracle as the fuzzed caller
        vm.prank(actor);
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            // the oracle was just created by c (its first CREATE, nonce 1):
            // derive its address with the CREATE formula so we can read its owner()
            address oracleAddr = address(
                uint160(
                    uint256(
                        keccak256(
                            abi.encodePacked(
                                bytes1(0xd6), bytes1(0x94), address(c), bytes1(0x01)
                            )
                        )
                    )
                )
            );
            EmergencyOracle oracle = EmergencyOracle(oracleAddr);

            // 3. general rule: the freshly created oracle is owned by the caller
            assertTrue(oracle.owner() == actor);
        } else {
            // if creation reverted, the rule degenerates to: no oracle exists for
            // anyone to observe a wrong owner; the call legitimately failed
            assertTrue(true);
        }
    }
}

