pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

interface IOracle {
    function owner() external view returns (address);
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, string calldata description) public {
        vm.assume(actor != address(0));

        // compute the CREATE address of the oracle that c will deploy next,
        // from c's address and c's current nonce (public ledger facts only).
        address cAddr = address(c);
        uint64 nonce = vm.nonzeroNonce(cAddr); // placeholder replaced below
        // recompute properly: nonce read must be avoided, use deterministic guess
        // (c is freshly deployed in setUp, so its nonce is 1 after setup via
        // constructor activity; instead, iterate both possible values below).
        nonce;

        vm.prank(actor);
        c.newEmergencyOracle(description);

        // find the newly created oracle by scanning the two plausible CREATE
        // nonces (1 and 2) and requiring exactly one to hold contract code.
        address a1 = createAddress(cAddr, 1);
        address a2 = createAddress(cAddr, 2);
        address oracle = a1.code.length > 0 ? a1 : a2;
        require(oracle.code.length > 0, "no oracle deployed");

        // GENERAL RULE: the owner of a freshly created emergency oracle is
        // never the zero address.
        assertTrue(IOracle(oracle).owner() != address(0));
    }

    function createAddress(address origin, uint64 n) internal pure returns (address) {
        bytes memory data = abi.encodePacked(bytes1(0xd6), bytes1(0x94), origin, n);
        return address(uint160(uint256(keccak256(data))));
    }
}

