pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(string calldata description, uint256 seed) public {
        // The only caller permitted by onlyJojoTeam is c.jojoTeam() (address(0)).
        // General rule: for ANY description, a call by the jojoTeam to newEmergencyOracle
        // succeeds and creates an oracle owned by the jojoTeam.
        vm.assume(bytes(description).length < 1024);
        if (seed % 2 == 0) {
            vm.warp(seed);
        } else {
            vm.roll(seed);
        }
        vm.prank(c.jojoTeam());
        bool ok;
        try c.newEmergencyOracle(description) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference always succeeds; the mutant reverts because it transfers
        // ownership to the zero address jojoTeam, which transferOwnership rejects.
        assertTrue(ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(string calldata description) public {
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(C.newEmergencyOracle.selector, description)
        );
        assert(ok);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public {
        require(msg.sender == c.jojoTeam(), "precondition: caller is the JOJO team");
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(!reverted);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 salt) public payable {
        require(true);
        address caller = address(this);
        address team = c.jojoTeam();
        bool reverted;
        string memory desc = "test";
        try c.newEmergencyOracle(desc) { reverted = false; } catch { reverted = true; }
        if (caller != team) {
            assert(reverted);
        } else {
            assert(!reverted);
        }
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public payable {
        require(true);
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted == (msg.sender == c.jojoTeam()));
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description, address newTeam) public payable {
        require(newTeam != address(this));
        c.setJojoTeam(newTeam);
        require(c.jojoTeam() != address(this));
        bool reverted;
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        assert(reverted == (msg.sender == c.jojoTeam()));
    }
    receive() external payable {}
}
